        (exec "ALT + space" menu)
        # Guard with `pidof hyprlock ||` (same as hypridle's lock_cmd): a second
        # hyprlock fights the first over the Goodix fingerprint device ("Device
        # already claimed"), breaking fingerprint AND password auth on the lock
        # you're typing into. Never stack a duplicate.
        (exec "${mainMod} + SHIFT + Q" "pidof hyprlock || ${config.programs.hyprlock.package}/bin/hyprlock")
        (exec "${mainMod} + SHIFT + S" "${pkgs.hyprshot}/bin/hyprshot -m region")
        (exec "${mainMod} + E" "emacsclient -c")

        (exec "${mainMod} + O" "makoctl dismiss --all")
        # Invoke the newest notification's default action, and let the app
        # raise itself: hyprctl mints an xdg-activation token, makoctl forwards
        # it, the app spends it on whichever of its own surfaces the
        # notification belongs to. See the two patches/ files for why the token
        # beats focusing by pid or class from out here.
        #
        # The shape check is not paranoia: an hyprctl that predates
        # patches/hyprland-activation-token-over-ipc.patch answers "unknown
        # request" on *stdout* with exit 0, so an unguarded pipe would forward
        # that as the token and suppress mako's own fallback mint. printf is a
        # shell builtin, so the token never reaches any argv.
        (exec "${mainMod} + SHIFT + O" ''t=$(hyprctl activationtoken 2>/dev/null); case $t in ????????-????-????-????-????????????) printf %s "$t" | makoctl invoke --token-stdin ;; *) makoctl invoke ;; esac'')

        # Force the physical outputs back on. After a VT switch away and back
        # (e.g. to a text console on tty1 and back via Ctrl+Alt+F3) panels can
        # stay DPMS-off even though Hyprland is foreground; this relights them.
        # Only works while Hyprland is the active VT.
        (exec "${mainMod} + SHIFT + D" "${hyprDpmsPhysical} on")

        (dsp "${mainMod} + B" ''hl.dsp.focus({ direction = "left" })'')
        (dsp "${mainMod} + F" ''hl.dsp.focus({ direction = "right" })'')
        (dsp "${mainMod} + P" ''hl.dsp.focus({ direction = "up" })'')
        (dsp "${mainMod} + N" ''hl.dsp.focus({ direction = "down" })'')
        (dsp "${mainMod} + SHIFT + B" ''hl.dsp.window.move({ direction = "left" })'')
        (dsp "${mainMod} + SHIFT + F" ''hl.dsp.window.move({ direction = "right" })'')
        (dsp "${mainMod} + SHIFT + P" ''hl.dsp.window.move({ direction = "up" })'')
        (dsp "${mainMod} + SHIFT + N" ''hl.dsp.window.move({ direction = "down" })'')

        (dsp "${mainMod} + SHIFT + left" ''hl.dsp.workspace.move({ monitor = "l" })'')
        (dsp "${mainMod} + SHIFT + right" ''hl.dsp.workspace.move({ monitor = "r" })'')
        (dsp "${mainMod} + SHIFT + up" ''hl.dsp.workspace.move({ monitor = "u" })'')
        (dsp "${mainMod} + SHIFT + down" ''hl.dsp.workspace.move({ monitor = "d" })'')

        (dsp "${mainMod} + M" "hl.dsp.window.fullscreen()")
